return function()
local start=(function()
return function(g, family, roster, controllerNames)
    local hero=g.myHero
    if not hero then return end
    local selected=roster[hero.charName]
    if not selected then
        if g.print then g.print('[AyyyyIO] No controller available for '..tostring(hero.charName)) end
        return
    end
    local previous=g.AyyyyIO
    if previous and previous.active then return previous end
    local base=hero.charName:match('^Jade_(.+)$') or hero.charName
    local controller=controllerNames and controllerNames[hero.charName]or base
    local provider=g.SDK
    local previousCore=provider.ChampionCore and provider.ChampionCore.active
    if previousCore and previousCore:Current()then
        error('A separate champion core is active; reload with one champion controller.')
    end
    local registry={active=true,loading=true,champion=hero.charName,build=family.generation}
    function registry:Allows()
        return self.active and family.active and g.OrbamaFamily==family and g.AyyyyIO==self
            and g.SDK==provider and g.myHero==hero
    end
    local preparationActive=function()return not registry.preparationStopped and registry:Allows()end
    function registry:GetPreparationScope(owner)
        if self.preparationStopped then return nil,'inactive_controller'end
        return family:GetPreparationScope('AyyyyIO',owner,preparationActive)
    end
    function registry:Shutdown(reason)
        if not self.active then return end
        self.active=false
        family:ClosePreparation('AyyyyIO')
        if self.controller and self.controller.Shutdown then self.controller:Shutdown(reason) end
        if self.core then self.core:Shutdown(reason or 'ayyyyio_shutdown')
        end
    end
    g.AyyyyIO=registry
    registry:GetPreparationScope('controller')
    if not g.OrbamaPrediction then family:Require('prediction') end
    local ok,value=pcall(family.Require,family,selected)
    local loadedCore=provider.ChampionCore and provider.ChampionCore.active
    registry.core=loadedCore~=previousCore and loadedCore or nil
    registry.loading=false
    -- A controller that returns without registering the common core is a failed
    -- load as well: nothing may stay registered, exactly as when it fails outright
    -- (same rule as tools/build_ayyyyio.py). The bare assert left the registry,
    -- its scopes and the loaded guard behind.
    if not ok or not value or not registry.core then
        registry:Shutdown('controller_load_failed')
        error(not ok and value or not value and 'Champion controller did not initialize' or 'Champion did not register the common core',0)
    end
    registry.controller=value
    registry.core:RegisterCleanup('ayyyyio_registry',function(reason)registry:Shutdown(reason)end)
    if value.Shutdown then
        local shutdown=value.Shutdown
        value.Shutdown=function(controller,...)
            registry.preparationStopped=true;family:ClosePreparation('AyyyyIO')
            return shutdown(controller,...)
        end
    end
    registry.core:Bind(provider.OnTick,function()
        if registry.active and not registry:Allows() then registry:Shutdown('instance_changed') end
    end,{first=true})
    return registry
end

end)()
